   869  // copy x86 detail information from internal structure to public structure
   870  static void update_pub_insn(cs_insn *pub, InternalInstruction *inter, uint8_t *prefixes)
   871  {
   872          prefixes[0] = inter->prefix0;
   873          prefixes[1] = inter->prefix1;
   874          prefixes[2] = inter->prefix2;
   875          prefixes[3] = inter->prefix3;
   876
   877          if (inter->vectorExtensionType != 0)
   878                  memcpy(pub->detail->x86.opcode, inter->vectorExtensionPrefix, sizeof(pub->detail->x86.opcode));
   879          else {
   880                  if (inter->twoByteEscape) {
   881                          if (inter->threeByteEscape) {
   882                                  pub->detail->x86.opcode[0] = inter->twoByteEscape;
   883                                  pub->detail->x86.opcode[1] = inter->threeByteEscape;
   884                                  pub->detail->x86.opcode[2] = inter->opcode;
   885                          } else {
   886                                  pub->detail->x86.opcode[0] = inter->twoByteEscape;
   887                                  pub->detail->x86.opcode[1] = inter->opcode;
   888                          }
   889                  } else {
   890                                  pub->detail->x86.opcode[0] = inter->opcode;
   891                  }
   892          }
   893
   894          pub->detail->x86.rex = inter->rexPrefix;
   895
   896          pub->detail->x86.addr_size = inter->addressSize;
   897
   898          pub->detail->x86.modrm = inter->orgModRM;
   899          pub->detail->x86.encoding.modrm_offset = inter->modRMOffset;
   900
   901          pub->detail->x86.sib = inter->sib;
   902          pub->detail->x86.sib_index = x86_map_sib_index(inter->sibIndex);
   903          pub->detail->x86.sib_scale = inter->sibScale;
   904          pub->detail->x86.sib_base = x86_map_sib_base(inter->sibBase);
   905
   906          pub->detail->x86.disp = inter->displacement;
   907          if (inter->consumedDisplacement) {
   908                  pub->detail->x86.encoding.disp_offset = inter->displacementOffset;
   909                  pub->detail->x86.encoding.disp_size = inter->displacementSize;
   910          }
   911
   912          pub->detail->x86.encoding.imm_offset = inter->immediateOffset;
   913          if (pub->detail->x86.encoding.imm_size == 0 && inter->immediateOffset != 0)
   914                  pub->detail->x86.encoding.imm_size = inter->immediateSize;
   915  }
